diag_summary <- tibble(
  test = c(
    "Breusch-Pagan test",
    "Durbin-Watson statistic",
    "Maximum VIF"
  ),
  result = c(
    bptest(mmm_model)$p.value,
    dwtest(mmm_model)$statistic[[1]],
    max(vif(mmm_model))
  )
)

